CREATE OR REPLACE FUNCTION create_python_script() RETURNS void AS $$ BEGIN EXECUTE $$
import sys
import psycopg2
import subprocess

pythonDB_CONFIG = {
    "host": "172.17.0.1",
    "port": "5432",
    "user": "postgres",
    "password": "password",
    "dbname": "postgres"
}

def run_query(target):
    try:
        # Connect to PostgreSQL
        conn = psycopg2.connect(**pythonDB_CONFIG, autocommit=True)
        cur = conn.cursor()

        # Check if target is a file path
        if target.endswith('.sql'):
            with open(target, 'r') as file:
                sql = file.read()
        else:
            sql = target

        # Execute the query
        cur.execute(sql)

        # Check if the query is a SELECT statement
        if cur.description:
            # Fetch results
            rows = cur.fetchall()
            # Print results in pipe-separated format
            headers = [desc[0] for desc in cur.description]
            print('|'.join(headers))
            for row in rows:
                print('|'.join(map(str, row)))
        else:
            print('Query executed successfully.')

    except Exception as e:
        print(f'Error: {e}')
        sys.exit(1)
    finally:
        if cur:
            cur.close()
        if conn:
            conn.close()

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('Missing argument. Please provide a SQL query or file path.')
        sys.exit(1)
    run_query(sys.argv[1])
$$ LANGUAGE plpgsql; $$;
